    import copy

    # Create a shallow copy of the object
    clone = copy.copy(self)

    # Iterate over all attributes of the object
    for attr, value in clone.__dict__.items():
        # Check if the value is a string that matches a relabel
        if isinstance(value, str) and value in relabels:
